import React, { useState, useRef, useCallback, useEffect } from 'react';
import Webcam from 'react-webcam';
import { attendanceAPI } from './api_service';
import {
  CheckCircle,
  XCircle,
  RefreshCw,
  UserCheck,
  Fingerprint,
  Volume2,
  VolumeX,
  Square,
  Clock
} from 'lucide-react';

const CameraRecognition = () => {
  const webcamRef = useRef(null);

  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [autoMode, setAutoMode] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);

  const getConfidenceColor = (conf) => {
    const value = (conf || 0) * 100;
    if (value > 80) return "#10B981";
    if (value > 60) return "#F59E0B";
    return "#EF4444";
  };

  const playSound = (type) => {
    if (!soundEnabled) return;

    const audio = new Audio(
      type === 'success'
        ? '/sounds/success.mp3'
        : '/sounds/error.mp3'
    );

    audio.play().catch(() => {
      console.warn("Audio blocked by browser");
    });
  };

  const handleCapture = useCallback(async () => {
    if (!webcamRef.current) return;

    setLoading(true);
    setError(null);

    try {
      const imageSrc = webcamRef.current.getScreenshot();

      if (!imageSrc) {
        throw new Error("Impossible de capturer l'image");
      }

      const response = await attendanceAPI.recognize(imageSrc);
      const data = response?.data;

      if (!data || !data.success) {
        throw new Error(data?.error || "Reconnaissance échouée");
      }

      setResult({
        name: typeof data.student === "string"
          ? data.student
          : `${data.student?.first_name || ""} ${data.student?.last_name || ""}`.trim(),

        email: data.email || "N/A",
        confidence: Number(data.confidence || 0),
        attendanceId: data.attendance_id || "N/A",
        time: new Date().toLocaleTimeString()
      });

      playSound('success');

    } catch (err) {
      setError(err.message || "Erreur reconnaissance");
      setResult(null);
      playSound('error');

    } finally {
      setLoading(false);
    }
  }, [soundEnabled]);

  // Auto mode
  useEffect(() => {
    let interval;

    if (autoMode) {
      interval = setInterval(() => {
        if (!loading) handleCapture();
      }, 5000);
    }

    return () => clearInterval(interval);
  }, [autoMode, loading, handleCapture]);

  return (
    <div style={styles.container}>

      {/* HEADER */}
      <div style={styles.header}>
        <h1 style={styles.title}>
          <UserCheck size={22} /> Face Recognition
        </h1>

        <button
          onClick={() => setSoundEnabled(!soundEnabled)}
          style={styles.iconBtn}
        >
          {soundEnabled ? <Volume2 /> : <VolumeX />}
        </button>
      </div>

      {/* CAMERA */}
      <div style={styles.cameraBox}>
        <Webcam
          ref={webcamRef}
          audio={false}
          screenshotFormat="image/jpeg"
          videoConstraints={{ facingMode: "user" }}
          style={styles.webcam}
        />

        {loading && (
          <div style={styles.loadingOverlay}>
            <RefreshCw className="spin" size={40} />
          </div>
        )}
      </div>

      {/* BUTTONS */}
      <div style={styles.actions}>

        <button
          onClick={handleCapture}
          disabled={loading || autoMode}
          style={{
            ...styles.btn,
            background: loading || autoMode ? "#94A3B8" : "#4F46E5"
          }}
        >
          <Fingerprint size={18} />
          Scan
        </button>

        <button
          onClick={() => setAutoMode(!autoMode)}
          style={{
            ...styles.btn,
            background: autoMode ? "#EF4444" : "#E2E8F0"
          }}
        >
          {autoMode ? <Square size={18} /> : <RefreshCw size={18} />}
          Auto
        </button>

      </div>

      {autoMode && (
        <p style={styles.autoText}>
          🔄 Auto scan actif
        </p>
      )}

      {/* RESULT */}
      <div style={styles.resultArea}>

        {result && (
          <div style={styles.card}>
            <div style={styles.cardHeader}>
              <CheckCircle color="#10B981" />
              <b>Étudiant détecté</b>
            </div>

            <p>{result.name}</p>
            <p>{result.email}</p>

            <div style={styles.row}>
              <span>
                <Clock size={14} /> {result.time}
              </span>

              <span style={{ color: getConfidenceColor(result.confidence) }}>
                {(result.confidence * 100).toFixed(1)}%
              </span>
            </div>

            <div style={styles.badge}>
              ID: {result.attendanceId}
            </div>
          </div>
        )}

        {error && (
          <div style={{ ...styles.card, borderLeft: "4px solid red" }}>
            <div style={styles.cardHeader}>
              <XCircle color="red" />
              <b>Erreur</b>
            </div>
            <p>{error}</p>
          </div>
        )}

      </div>
    </div>
  );
};

const styles = {
  container: { padding: 20, maxWidth: 600, margin: "auto" },
  header: { display: "flex", justifyContent: "space-between" },
  title: { display: "flex", gap: 8, alignItems: "center" },
  iconBtn: { border: "none", background: "transparent", cursor: "pointer" },

  cameraBox: { position: "relative", marginTop: 15 },
  webcam: { width: "100%", borderRadius: 12 },

  loadingOverlay: {
    position: "absolute",
    inset: 0,
    display: "grid",
    placeItems: "center",
    background: "rgba(0,0,0,0.4)",
    color: "white"
  },

  actions: { display: "flex", gap: 10, marginTop: 15 },

  btn: {
    flex: 1,
    padding: 12,
    border: "none",
    borderRadius: 10,
    color: "white",
    cursor: "pointer",
    display: "flex",
    gap: 8,
    justifyContent: "center"
  },

  autoText: { textAlign: "center", marginTop: 10 },

  resultArea: { marginTop: 20 },

  card: {
    padding: 15,
    border: "1px solid #E2E8F0",
    borderRadius: 10,
    background: "white"
  },

  cardHeader: {
    display: "flex",
    alignItems: "center",
    gap: 10,
    marginBottom: 10
  },

  row: {
    display: "flex",
    justifyContent: "space-between",
    marginTop: 10
  },

  badge: {
    marginTop: 8,
    background: "#F1F5F9",
    padding: "4px 8px",
    borderRadius: 6,
    fontSize: 12
  }
};

export default CameraRecognition;
